# Custom CUDA source for naive 2D convolution (square kernel)
conv2d_kernel = """
__global__ void conv2d_kernel(const float* __restrict__ input,
                               const float* __restrict__ weight,
                               float* output,
                               int stride, int padding, int dilation,
                               int out_channels, int in_channels,
                               int height_in, int width_in) {
        // Compute output spatial size
        int out_h = (height_in + 2 * padding - dilation * (kernel_size - 1)) / stride + 1;
        int out_w = (width_in + 2 * padding - dilation * (kernel_size - 1)) / stride + 1;

        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        if (idx < out_h * out_w) {
            float sum = 0.0f;
            for (int oc = 0; oc < out_channels; ++oc) {
                for (int ic = 0; ic < in_channels; ++ic) {
                    for (int kh = -dilation; kh < dilation + kernel_size; ++kh) {
                        int ih = kh * stride + padding;
                        if (ih < 0 || ih >= height_in) continue;
                        for (int kw = -dilation; kw < dilation + kernel_size; ++kw) {
                            int iw = kw * stride + padding;
                            if (iw < 0 || iw >= width_in) continue;

                            // weight index: [oc, ic, kh+offset?, kw+offset?]
                            // Assume weight layout is (out_channels, in_channels, ksize, ksize)
                            int w_idx = ((oc * in_channels + ic) * kernel_size * kernel_size +
                                          kh * kernel_size * kernel_size +
                                          kw * kernel_size * kernel_size);
                            float val = weight[w_idx];
                            sum += val * input[ih * width_in + iw];
                        }
                    }
                }
            }
            int out_idx = idx;
            output[out_idx] = sum;
        }
    }
}

torch::Tensor conv2d_cuda(torch::Tensor x, torch::Tensor w,
                         int stride, int padding, int dilation,
                         int out_channels) {
    auto in_h = x.size(3);
    auto in_w = x.size(4);
    auto out_shape = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (out_h * out_w + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float()>, w.data_ptr<float()>,
                                              out_shape.data_ptr<float()>,
                                              stride, padding, dilation,
                                              out_channels, x.size(2), in_h, in_w);
    return out_shape;
}
"""

